return ['domain'=>'publishpress-authors','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'fr_FR','project-id-version'=>'PublishPress Authors 4.20.0','pot-creation-date'=>'2026-11-12T07:29:08+00:00','po-revision-date'=>'2026-11-12 09:12+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Authors'=>'PublishPress Authors','https://wordpress.org/plugins/publishpress-authors/'=>'https://wordpress.org/plugins/publishpress-authors/','PublishPress Authors allows you to add multiple authors and guest authors to WordPress posts'=>'PublishPress Authors vous permet d\'ajouter plusieurs auteurs et auteurs invités aux articles WordPress','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Upgrade to Pro'=>'Passer à Pro','This plugin can be deleted.'=>'Ce plugin peut être supprimé.','Actions provided by PublishPress plugins.'=>'Actions fournies par les plugins PublishPress.','List Authors'=>'Liste des auteurs','Lists PublishPress Authors. Results never include author email addresses.'=>'Liste des auteurs PublishPress. Les résultats n\'incluent jamais les adresses e-mail des auteurs.','Get Author'=>'Obtenir l\'auteur','Gets one PublishPress Author by term ID. The response never includes an email address.'=>'Récupère un auteur PublishPress par l\'ID de terme. La réponse n\'inclut jamais d\'adresse e-mail.','Get Post Authors'=>'Obtenir les auteurs de l\'article','Gets the ordered PublishPress Authors assigned to one editable post. The response never includes author email addresses.'=>'Récupère les auteurs PublishPress ordonnés assignés à un article modifiable. La réponse n\'inclut jamais les adresses e-mail des auteurs.','Get Author Fields'=>'Obtenir les champs de l\'auteur','Lists enabled author-profile field definitions without exposing profile values.'=>'Liste les définitions des champs de profil d\'auteur activés sans exposer les valeurs de profil.','Author not found.'=>'Auteur non trouvé.','Post not found.'=>'Article non trouvé.','Authors List'=>'Liste des auteurs','Display authors list.'=>'Afficher la liste des auteurs.','Title'=>'Titre','Layout'=>'Mise en page','Display All Authors (including those who have not written any posts)'=>'Afficher tous les auteurs (y compris ceux qui n\'ont écrit aucun article)','Enable author\'s search box'=>'Activer la zone de recherche de l\'auteur','Limits per page'=>'Limites par page','Authors'=>'Auteurs','Order'=>'Ordre','Order by'=>'Trier par','Grid Columns'=>'Colonnes de la grille','Author\'s search box field (Seperate multiple fields by comma(\',\'))'=>'Champ de la zone de recherche de l\'auteur (Séparez plusieurs champs par une virgule(\',\'))','All Authors'=>'Tous les auteurs','Guest Authors'=>'Auteurs invités','Users Authors'=>'Auteurs utilisateurs','Ascending'=>'Ascendant','Descending'=>'Descendant','Name'=>'Nom','Post Counts'=>'Nombre d\'articles','First Name'=>'Prénom','Last Name'=>'Nom de famille','Showing authors starting with %s'=>'Affichage des auteurs commençant par %s','Showing all authors'=>'Affichage de tous les auteurs','No authors found.'=>'Aucun auteur trouvé.','Loading authors...'=>'Chargement des auteurs...','Unable to load authors.'=>'Impossible de charger les auteurs.','Default Search'=>'Recherche par défaut','Search Box'=>'Zone de recherche','Search'=>'Recherche','Search authors'=>'Rechercher des auteurs','Search authors by'=>'Rechercher des auteurs par','No recent posts from this author'=>'Aucun post récent de cet auteur','Request status.'=>'Statut de la demande.','Security error. Kindly reload this page and try again'=>'Erreur de sécurité. Veuillez recharger cette page et réessayer','You cannot edit an author profile linked to an administrator account.'=>'Vous ne pouvez pas modifier un profil d\'auteur lié à un compte administrateur.','You do not have permission to edit this author profile because it is linked to a user account you do not have permission to edit.'=>'Vous n\'avez pas la permission de modifier ce profil d\'